// Single-file example from https://github.com/Rahulchaube1/blyx-classification/tree/v0.1.1
// Rows in a confusion vector are [true positives, false positives, true negatives, false negatives].
pub fn class_probability(score: f64) -> bool {
    score >= 0.0 && score <= 1.0
}

pub fn class_label(value: f64) -> bool {
    value == 0.0 || value == 1.0
}

pub fn class_positive(score: f64, threshold: f64) -> bool {
    score >= threshold
}

pub fn class_confusion(labels: vector, scores: vector, threshold: f64) -> vector {
    if len(labels) == 0 || len(labels) != len(scores) || !class_probability(threshold) { return []; }
    let mut tp = 0.0;
    let mut fp = 0.0;
    let mut tn = 0.0;
    let mut missed = 0.0;
    let mut i = 0;
    while i < len(labels) {
        let label = at(labels, i);
        let score = at(scores, i);
        if !class_label(label) || !class_probability(score) { return []; }
        if class_positive(score, threshold) {
            if label == 1.0 { tp += 1.0; } else { fp += 1.0; }
        } else {
            if label == 1.0 { missed += 1.0; } else { tn += 1.0; }
        }
        i += 1;
    }
    [tp, fp, tn, missed]
}

fn ratio(numerator: f64, denominator: f64) -> f64 {
    if denominator == 0.0 { return 0.0; }
    numerator / denominator
}

pub fn class_precision(tp: f64, fp: f64) -> f64 { ratio(tp, tp + fp) }
pub fn class_recall(tp: f64, missed: f64) -> f64 { ratio(tp, tp + missed) }
pub fn class_f1(tp: f64, fp: f64, missed: f64) -> f64 { ratio(2.0 * tp, 2.0 * tp + fp + missed) }
pub fn class_cost(fp: f64, missed: f64, fp_cost: f64, fn_cost: f64) -> f64 {
    fp * fp_cost + missed * fn_cost
}

fn main() {
    let table = class_confusion([1, 0, 1, 0], [0.9, 0.6, 0.4, 0.1], 0.5);
    println!(class_precision(at(table, 0), at(table, 1)));
    println!(class_recall(at(table, 0), at(table, 3)));
    println!(class_cost(at(table, 1), at(table, 3), 1.0, 5.0));
}

// Single-file example from https://github.com/Rahulchaube1/blyx-calibration/tree/v0.1.1
pub fn cal_squared_error(label: f64, score: f64) -> f64 {
    let diff = score - label;
    diff * diff
}

fn valid(labels: vector, scores: vector) -> bool {
    if len(labels) == 0 || len(labels) != len(scores) { return false; }
    let mut i = 0;
    while i < len(labels) {
        let y = at(labels, i);
        let p = at(scores, i);
        if !(y == 0.0 || y == 1.0) || !(p >= 0.0 && p <= 1.0) { return false; }
        i += 1;
    }
    true
}

pub fn cal_brier(labels: vector, scores: vector) -> f64 {
    if !valid(labels, scores) { return -1.0; }
    let mut total = 0.0;
    let mut i = 0;
    while i < len(labels) {
        total += cal_squared_error(at(labels, i), at(scores, i));
        i += 1;
    }
    total / at([len(labels)], 0)
}

// Return [count, sum of scores, sum of outcomes] so empty bins remain distinguishable.
fn bin_totals(labels: vector, scores: vector, index: i64, bins: i64) -> vector {
    let width = at([bins], 0);
    let lo = at([index], 0) / width;
    let hi = at([index + 1], 0) / width;
    let mut count = 0.0;
    let mut forecast = 0.0;
    let mut observed = 0.0;
    let mut i = 0;
    while i < len(labels) {
        let p = at(scores, i);
        if p >= lo && (p < hi || index == bins - 1) {
            count += 1.0; forecast += p; observed += at(labels, i);
        }
        i += 1;
    }
    [count, forecast, observed]
}

pub fn cal_bin(labels: vector, scores: vector, index: i64, bins: i64) -> vector {
    if !valid(labels, scores) || bins < 1 || bins > 100 || index < 0 || index >= bins { return []; }
    bin_totals(labels, scores, index, bins)
}

pub fn cal_ece(labels: vector, scores: vector, bins: i64) -> f64 {
    if !valid(labels, scores) || bins < 1 || bins > 100 { return -1.0; }
    let mut error = 0.0;
    let mut i = 0;
    while i < bins {
        let bin = bin_totals(labels, scores, i, bins);
        let gap = at(bin, 1) - at(bin, 2);
        if gap < 0.0 { error -= gap; } else { error += gap; }
        i += 1;
    }
    error / at([len(labels)], 0)
}

fn main() {
    let labels = [0, 0, 1, 1];
    let scores = [0.25, 0.25, 0.75, 0.75];
    println!(cal_brier(labels, scores));
    println!(cal_ece(labels, scores, 2));
}

// Single-file example from https://github.com/Rahulchaube1/blyx-retrieval/tree/v0.1.1
fn document_id(value: f64) -> bool {
    value >= 0.0 && value <= 9007199254740991.0 && value % 1.0 == 0.0
}
fn occurs_before(items: vector, end: i64, item: f64) -> bool {
    let mut i = 0;
    while i < end {
        if at(items, i) == item { return true; }
        i += 1;
    }
    false
}
// Binary judgments for one query. Duplicate retrieved IDs consume their rank without scoring twice.
pub fn retrieval_at_k(ranked: vector, relevant: vector, k: i64) -> vector {
    if k <= 0 || len(relevant) == 0 { return []; }
    let mut judged = 0.0;
    let mut j = 0;
    while j < len(relevant) {
        let id = at(relevant, j);
        if !document_id(id) { return []; }
        if !occurs_before(relevant, j, id) { judged += 1.0; }
        j += 1;
    }
    let mut hits = 0.0;
    let mut reciprocal = 0.0;
    let mut sum_precision = 0.0;
    let mut i = 0;
    while i < k && i < len(ranked) {
        let id = at(ranked, i);
        if !document_id(id) { return []; }
        if occurs_before(relevant, len(relevant), id) && !occurs_before(ranked, i, id) {
            hits += 1.0;
            let rank = at([i + 1], 0);
            if hits == 1.0 { reciprocal = 1.0 / rank; }
            sum_precision += hits / rank;
        }
        i += 1;
    }
    let cutoff = at([k], 0);
    let divisor = if judged < cutoff { judged } else { cutoff };
    [hits / cutoff, hits / judged, reciprocal, sum_precision / divisor]
}

fn main() {
    let result = retrieval_at_k([7, 7, 9, 12], [7, 9], 3);
    println!(at(result, 1));
    println!(at(result, 2));
}

// Single-file example from https://github.com/Rahulchaube1/blyx-backtest/tree/v0.1.1
// All fold positions are zero-based, with exclusive end positions.
pub fn bt_fold_count(n: i64, initial: i64, horizon: i64, gap: i64) -> i64 {
    if n < 0 || initial < 1 || horizon < 1 || gap < 0 { return -1; }
    if initial >= n || gap >= n - initial { return 0; }
    (n - initial - gap) / horizon
}

fn train_start(end: i64, window: i64) -> i64 {
    if window > 0 && window < end { return end - window; }
    0
}

pub fn bt_fold(n: i64, initial: i64, horizon: i64, gap: i64, window: i64, fold: i64) -> vector {
    let folds = bt_fold_count(n, initial, horizon, gap);
    if window < 0 || fold < 0 || fold >= folds { return []; }
    let end = initial + fold * horizon;
    let first_test = end + gap;
    [train_start(end, window), end, first_test, first_test + horizon]
}

fn finite(x: f64) -> bool { x - x == 0.0 }
fn absolute(x: f64) -> f64 { if x < 0.0 { return -x; } x }
fn valid_series(values: vector) -> bool {
    let mut i = 0;
    while i < len(values) {
        if !finite(at(values, i)) { return false; }
        i += 1;
    }
    true
}

// Return [scored rows, last-value MAE, training-mean MAE].
pub fn bt_baselines(series: vector, initial: i64, horizon: i64, gap: i64, window: i64) -> vector {
    let folds = bt_fold_count(len(series), initial, horizon, gap);
    if folds <= 0 || window < 0 || !valid_series(series) { return []; }
    let rows = at([folds * horizon], 0);
    let mut last_mae = 0.0;
    let mut mean_mae = 0.0;
    let mut previous_start = 0;
    let mut previous_end = 0;
    let mut training_sum = 0.0;
    let mut fold = 0;
    while fold < folds {
        let end = initial + fold * horizon;
        let start = train_start(end, window);
        if start >= previous_end {
            training_sum = 0.0;
            previous_end = start;
        } else {
            let mut drop = previous_start;
            while drop < start {
                training_sum -= at(series, drop);
                drop += 1;
            }
        }
        while previous_end < end {
            training_sum += at(series, previous_end);
            previous_end += 1;
        }
        if !finite(training_sum) { return []; }
        previous_start = start;
        let mean = training_sum / at([end - start], 0);
        let last = at(series, end - 1);
        let mut t = end + gap;
        let test_end = t + horizon;
        while t < test_end {
            let actual = at(series, t);
            last_mae += absolute(last - actual) / rows;
            mean_mae += absolute(mean - actual) / rows;
            t += 1;
        }
        fold += 1;
    }
    if !finite(last_mae) || !finite(mean_mae) { return []; }
    [rows, last_mae, mean_mae]
}

// Supply one forecast per scored observation, in fold order.
pub fn bt_score(series: vector, forecasts: vector, initial: i64, horizon: i64, gap: i64) -> vector {
    let folds = bt_fold_count(len(series), initial, horizon, gap);
    if folds <= 0 { return []; }
    let count = folds * horizon;
    if len(forecasts) != count || !valid_series(series) || !valid_series(forecasts) { return []; }
    let first = initial + gap;
    let rows = at([count], 0);
    let mut mae = 0.0;
    let mut bias = 0.0;
    let mut i = 0;
    while i < count {
        let error = at(forecasts, i) - at(series, first + i);
        mae += absolute(error) / rows;
        bias += error / rows;
        i += 1;
    }
    if !finite(mae) || !finite(bias) { return []; }
    [rows, mae, bias]
}

fn main() {
    let demand = [10, 20, 30, 40, 50, 60, 70, 80];
    let baselines = bt_baselines(demand, 3, 2, 1, 2);
    println!(at(baselines, 0));
    println!(at(baselines, 1));
    println!(at(baselines, 2));
    let model = bt_score(demand, [45, 55, 65, 75], 3, 2, 1);
    println!(at(model, 1));
}

// https://github.com/Rahulchaube1/blyx-moments/blob/v0.1.0/moments.blyx
// A paired summary stores [count, mean_x, mean_y, Sxx, Sxy, Syy].
fn moments_finite(x: f64) -> bool { x - x == 0.0 }

pub fn mom_empty() -> vector { [0, 0, 0, 0, 0, 0] }

pub fn mom_valid(s: vector) -> bool {
    if len(s) != 6 { return false; }
    let n = at(s, 0);
    if !(n >= 0.0 && n <= 9007199254740991.0) || n % 1.0 != 0.0 { return false; }
    let mut i = 1;
    while i < 6 {
        if !moments_finite(at(s, i)) || (n == 0.0 && at(s, i) != 0.0) { return false; }
        i += 1;
    }
    at(s, 3) >= 0.0 && at(s, 5) >= 0.0
}

pub fn mom_update(s: vector, x: f64, y: f64) -> vector {
    if !mom_valid(s) || !moments_finite(x) || !moments_finite(y) { return []; }
    if at(s, 0) == 0.0 { return [1, x, y, 0, 0, 0]; }
    let n = at(s, 0) + 1.0;
    let dx = x - at(s, 1);
    let dy = y - at(s, 2);
    let mx = at(s, 1) + dx / n;
    let my = at(s, 2) + dy / n;
    let next = [n, mx, my, at(s, 3) + dx * (x - mx),
                at(s, 4) + dx * (y - my), at(s, 5) + dy * (y - my)];
    if !mom_valid(next) { return []; }
    next
}

pub fn mom_summary(x: vector, y: vector) -> vector {
    if len(x) != len(y) { return []; }
    let mut state = mom_empty();
    let mut i = 0;
    while i < len(x) {
        state = mom_update(state, at(x, i), at(y, i));
        if len(state) == 0 { return []; }
        i += 1;
    }
    state
}

pub fn mom_merge(a: vector, b: vector) -> vector {
    if !mom_valid(a) || !mom_valid(b) { return []; }
    if at(a, 0) == 0.0 { return b; }
    if at(b, 0) == 0.0 { return a; }
    let n = at(a, 0) + at(b, 0);
    let share = at(b, 0) / n;
    let weight = at(a, 0) * share;
    let dx = at(b, 1) - at(a, 1);
    let dy = at(b, 2) - at(a, 2);
    let next = [n, at(a, 1) + dx * share, at(a, 2) + dy * share,
                (at(a, 3) + at(b, 3)) + (dx * weight) * dx,
                (at(a, 4) + at(b, 4)) + (dx * weight) * dy,
                (at(a, 5) + at(b, 5)) + (dy * weight) * dy];
    if !mom_valid(next) { return []; }
    next
}

// Reduce to [1,4) before Newton iteration, including for subnormal variance.
fn moments_positive_root(value: f64) -> f64 {
    if value == 0.0 { return 0.0; }
    let mut v = value;
    let mut factor = 1.0;
    while v >= 4.0 { v /= 4.0; factor *= 2.0; }
    while v < 1.0 { v *= 4.0; factor /= 2.0; }
    let mut root = 2.0;
    let mut i = 0;
    while i < 6 { root = 0.5 * (root + v / root); i += 1; }
    root * factor
}

pub fn mom_sample_sd_y(s: vector) -> f64 {
    if !mom_valid(s) || at(s, 0) < 2.0 { return -1.0; }
    moments_positive_root(at(s, 5) / (at(s, 0) - 1.0))
}

// https://github.com/Rahulchaube1/blyx-linearfit/blob/v0.1.1/linearfit.blyx
fn linearfit_finite(x: f64) -> bool { x - x == 0.0 }

pub fn lf_start() -> vector { mom_empty() }
pub fn lf_update(s: vector, x: f64, y: f64) -> vector { mom_update(s, x, y) }
pub fn lf_merge(a: vector, b: vector) -> vector { mom_merge(a, b) }

// Model is centered at the sample means to preserve precision in prediction.
// penalty multiplies slope squared in the unnormalized sum-of-squares objective.
pub fn lf_finish(s: vector, penalty: f64) -> vector {
    if !mom_valid(s) || at(s, 0) < 2.0 || !linearfit_finite(penalty) || penalty < 0.0 { return []; }
    let denominator = at(s, 3) + penalty;
    if denominator <= 0.0 || !linearfit_finite(denominator) { return []; }
    let slope = at(s, 4) / denominator;
    if !linearfit_finite(slope) { return []; }
    [at(s, 1), at(s, 2), slope]
}

pub fn lf_fit(x: vector, y: vector, penalty: f64) -> vector {
    lf_finish(mom_summary(x, y), penalty)
}

pub fn lf_predict(model: vector, x: f64) -> f64 {
    if len(model) != 3 || !linearfit_finite(x) { return 0.0 / 0.0; }
    let y = at(model, 1) + at(model, 2) * (x - at(model, 0));
    if !linearfit_finite(y) { return 0.0 / 0.0; }
    y
}

fn main() {
    let training = lf_fit([1, 2, 3, 4], [3, 5, 7, 9], 0.0);
    println!(at(training, 2));
    println!(lf_predict(training, 5.0));
}

// https://github.com/Rahulchaube1/blyx-conformal/blob/v0.1.0/conformal.blyx
fn conformal_finite(x: f64) -> bool { x - x == 0.0 }
fn conformal_absolute(x: f64) -> f64 { if x < 0.0 { return -x; } x }

// ceil((n+1) * numerator / denominator), without a large intermediate product.
pub fn cf_rank(n: i64, numerator: i64, denominator: i64) -> i64 {
    if n < 1 || n > 9007199254740991 || numerator < 1 || numerator >= denominator || denominator > 1000000 { return 0; }
    let m = n + 1;
    let remainder = (m % denominator) * numerator;
    (m / denominator) * numerator + (remainder + denominator - 1) / denominator
}

fn conformal_score(values: vector, predictions: vector, i: i64, paired: bool) -> f64 {
    if paired { return conformal_absolute(at(values, i) - at(predictions, i)); }
    at(values, i)
}

fn conformal_select_radius(values: vector, predictions: vector, paired: bool, num: i64, den: i64) -> vector {
    let n = len(values);
    let rank = cf_rank(n, num, den);
    if rank == 0 || rank > n || (paired && len(predictions) != n) { return []; }
    let mut lo = conformal_score(values, predictions, 0, paired);
    let mut hi = lo;
    let mut i = 0;
    while i < n {
        let x = conformal_score(values, predictions, i, paired);
        if !conformal_finite(x) || x < 0.0 { return []; }
        if x < lo { lo = x; }
        if x > hi { hi = x; }
        i += 1;
    }
    // Each pass contracts to actual observed scores. Tied values need no special ordering.
    while lo < hi {
        let pivot = lo + (hi - lo) * 0.5;
        let mut below = 0;
        let mut equal = 0;
        let mut largest_below = lo;
        let mut smallest_above = hi;
        i = 0;
        while i < n {
            let x = conformal_score(values, predictions, i, paired);
            if x < pivot {
                below += 1;
                if x > largest_below { largest_below = x; }
            } else if x > pivot {
                if x < smallest_above { smallest_above = x; }
            } else { equal += 1; }
            i += 1;
        }
        if rank <= below { hi = largest_below; }
        else if rank > below + equal { lo = smallest_above; }
        else { return [pivot, rank, n]; }
    }
    [lo, rank, n]
}

pub fn cf_radius(scores: vector, numerator: i64, denominator: i64) -> vector {
    conformal_select_radius(scores, [], false, numerator, denominator)
}

pub fn cf_calibrate(actual: vector, predicted: vector, numerator: i64, denominator: i64) -> vector {
    conformal_select_radius(actual, predicted, true, numerator, denominator)
}

pub fn cf_interval(prediction: f64, radius: f64) -> vector {
    let low = prediction - radius;
    let high = prediction + radius;
    if radius < 0.0 || !conformal_finite(low) || !conformal_finite(high) { return []; }
    [low, high]
}

pub fn cf_coverage(actual: vector, predicted: vector, radius: f64) -> f64 {
    if !conformal_finite(radius) || radius < 0.0 || len(actual) == 0 || len(actual) != len(predicted) { return -1.0; }
    let mut hits = 0.0;
    let mut i = 0;
    while i < len(actual) {
        let r = conformal_absolute(at(actual, i) - at(predicted, i));
        if !conformal_finite(r) { return -1.0; }
        if r <= radius { hits += 1.0; }
        i += 1;
    }
    hits / at([len(actual)], 0)
}

