    if len(equity) == 0 {
        return [];
    }
    let mut high = at(equity, 0);
    let mut run = 0;
    let mut longest = 0;
    let mut recover = 0;
    let mut i = 1;
    while i < len(equity) {
        let x = at(equity, i);
        if x >= high {
            run = 0;
            high = x;
            recover = i;
        } else {
            run += 1;
            if run > longest {
                longest = run;
            }
        }
        i += 1;
    }
    [longest, run, recover]
}

